code.phat_variants.py:
"""PHAT-JeT trigger-scale variants, Keras 3 / HGQ2, synthesizable through da4ml.

Derived from github.com/aaronw5/phat-jet-hw scripts/phat_jet_k3.py (one PHAT block, static
GMP grid as one-hot scatter/gather, no LayerNorm, logits output). Adds the knobs needed to
search the CTL2 envelope (<=173k LUT, <30 stages @ 300 MHz):

  global_mode : "mha"   exact MHA over patch tokens (paper / July campaign)
                "mix"   token mixing with a constant-weight Dense over the NP*D flattened
                        tokens -> D (no activation x activation multiply)
                "mean"  single mean token broadcast through a Dense (cheapest)
                "none"
  local_mode  : "mha" | "none"
  gmp_mode    : "grid"  2-D one-hot grid (G^2 cells)      cost ~ 2*N*G^2*C
                "sep"   separable: eta-grid and phi-grid 1-D passes  cost ~ 4*N*G*C
                "none"
  gmp_channels: channels that pass through GMP (rest skip it); <= d_model
  pre_norm    : "tanh" bounded pre-activation on the embedding (July campaign) | None
  ffn_mult    : FFN hidden width multiplier (campaign used 1, paper 4)
  attn_bits   : if set, caps the fractional bits of Q and K data lanes (cheaper QK multiplies)

The same function builds the float model (quantized=False) and the HGQ model, so float
weights load 1:1 into the Q model by layer name.
"""
import numpy as _np
import keras
from keras import layers, ops


def _dense(units, q, activation=None, name=None):
    if q:
        from hgq.layers import QDense
        return QDense(units, activation=activation, name=name)
    return layers.Dense(units, activation=activation, name=name)


UNSHARED = {"on": False}
LUT = {"roles": set(), "d_hl": 8, "table": (6, 5)}  # roles: embed, ffn, mix, proj, head


def _ldense(role, units, q, activation=None, name=None, per_particle=False):
    """Dense, or HGQ learned-LUT dense (QDenseT: every input->output edge is a learned 1-D function stored as a
    lookup table) when `role` is enabled and the model is quantized."""
    if q and role in LUT["roles"]:
        from hgq.layers.table.dense import QDenseT
        return QDenseT(units, n_hl=1, d_hl=LUT["d_hl"], activation=activation, table_spec=LUT["table"], name=name)
    return (_pdense if per_particle else _dense)(units, q, activation=activation, name=name)


def _pdense(units, q, activation=None, name=None):
    """Per-particle Dense: shared weights (default) or position-specific weights when UNSHARED is on.
    Returns a callable taking the [B,N,F] tensor (N must be static for the per-slot kernel)."""
    if not UNSHARED["on"]:
        return _dense(units, q, activation=activation, name=name)

    def apply(x):
        N = x.shape[1]
        if q:
            from hgq.layers import QEinsumDense
            L = QEinsumDense("bnf,nfd->bnd", output_shape=(N, units), activation=activation, bias_axes="nd", name=name)
        else:
            L = layers.EinsumDense("bnf,nfd->bnd", output_shape=(N, units), activation=activation, bias_axes="nd", name=name)
        return L(x)

    return apply


ATTN_FLOORS = {"f": None, "i": None, "wbits": None}  # set by build_q_from_args (--attn_floor/--attn_ifloor/--attn_wbits)


def _attn_dlane():
    """Data-lane quantizer config with the attention floors on fractional and integer bits, or None. Applied to the
    INPUT quantizers of attention sub-layers: HGQ quantizes layer inputs, so floors on output quantizers (the old
    --attn_floor) never bound and attention collapsed to a constant (diag_attn.py, 2026-10-08)."""
    if ATTN_FLOORS["f"] is None and ATTN_FLOORS["i"] is None:
        return None
    from hgq.config import QuantizerConfig
    from hgq.constraints import MinMax
    c = QuantizerConfig("default", "datalane")
    if ATTN_FLOORS["f"] is not None:
        c.config["fc"] = MinMax(ATTN_FLOORS["f"], 16)
    if ATTN_FLOORS["i"] is not None:
        c.config["ic"] = MinMax(ATTN_FLOORS["i"], 12)
    return c


def _attn_wconf():
    """Weight quantizer config with a minimum bit width for attention projections, or None."""
    if ATTN_FLOORS["wbits"] is None:
        return None
    from hgq.config import QuantizerConfig
    from hgq.constraints import MinMax
    c = QuantizerConfig("default", "weight")
    c.config["bc"] = MinMax(ATTN_FLOORS["wbits"], 23)
    return c


def _einsum(eq, xs, q, name=None):
    if q:
        from hgq.layers import QEinsum
        dl = _attn_dlane() if name and "attn" in name else None
        return (QEinsum(eq, name=name, iq_confs=[dl] * len(xs)) if dl is not None else QEinsum(eq, name=name))(xs)
    return ops.einsum(eq, *xs)


PHAT_PARALLEL = {"on": False}  # --phat_parallel: GMP / local attention / global stage as parallel branches of one block
ATTN_NORM = {"mode": "softmax"}  # "relu": softmax-free attention, w = relu(q.k) -- no exp / reciprocal on the latency path


def _softmax(x, q, name=None, exp_i_max=5):
    if ATTN_NORM["mode"] == "linear":  # no nonlinearity on the scores (linear attention)
        return x
    if ATTN_NORM["mode"] == "relu":
        # softmax-free attention: the exp + 1/sum chain dominated PHAT's critical path (150-200 ns in alkaid);
        # relu scores keep the sparsity of attention, the normalisation is absorbed into the learned Q/K scale
        return layers.ReLU(name=name)(x)
    if q:
        from hgq.config import QuantizerConfig
        from hgq.constraints import MinMax
        from hgq.layers import QSoftmax
        exp_iq = QuantizerConfig("default", "datalane")
        exp_iq.config["ic"] = MinMax(-16, exp_i_max)
        dl = _attn_dlane()
        if dl is None:
            return QSoftmax(axis=-1, name=name, exp_iq_conf=exp_iq)(x)
        if ATTN_FLOORS["f"] is not None:
            exp_iq.config["fc"] = MinMax(ATTN_FLOORS["f"], 16)
        inv_iq = QuantizerConfig("default", "datalane")
        if ATTN_FLOORS["f"] is not None:
            inv_iq.config["fc"] = MinMax(ATTN_FLOORS["f"], 16)
        return QSoftmax(axis=-1, name=name, iq_conf=dl, enable_iq=True, exp_iq_conf=exp_iq, inv_iq_conf=inv_iq)(x)
    return layers.Softmax(axis=-1, name=name)(x)


ATTN_FLOOR = {"f": None}  # set by train_variant: min fractional bits on attention data lanes


def _qdense_bits(units, q, fbits, name):
    """Dense whose OUTPUT data lane has fractional bits in [ATTN_FLOOR, fbits] (Q/K/V/O lanes).
    The floor stops the EBOPs penalty from collapsing the attention path to ~1 bit."""
    lo, hi = ATTN_FLOOR["f"], fbits
    dl, wc = (_attn_dlane(), _attn_wconf()) if q else (None, None)
    if q and (lo is not None or hi is not None or dl is not None or wc is not None):
        from hgq.config import QuantizerConfig
        from hgq.constraints import MinMax
        from hgq.layers import QDense
        kw = {}
        if lo is not None or hi is not None:
            oq = QuantizerConfig("default", "datalane")
            oq.config["fc"] = MinMax(lo if lo is not None else -16, hi if hi is not None else 16)
            kw["oq_conf"] = oq
        if dl is not None:
            kw["iq_conf"] = dl
        if wc is not None:
            kw["kq_conf"] = wc
        return QDense(units, name=name, **kw)
    return _dense(units, q, name=name)


def _bin_indicator(lo, hi, first, last):
    if first:
        return lambda x: ops.cast(x < hi, x.dtype)
    if last:
        return lambda x: ops.cast(x >= lo, x.dtype)
    return lambda x: ops.cast((x >= lo) & (x < hi), x.dtype)


def onehot_bins(coord, edges, q, tag):
    edges = list(edges)
    nb = len(edges) - 1
    n = coord.shape[1]
    cols = []
    for g in range(nb):
        f = _bin_indicator(edges[g], edges[g + 1], g == 0, g == nb - 1)
        if q:
            from hgq.config import QuantizerConfig
            from hgq.layers import QUnaryFunctionLUT
            # the indicator is exactly 0 or 1: fixed 1-bit unsigned output (1 integer bit, saturating, not trainable).
            # With the scope default i0=0 (from-scratch QAT) a 1 wrapped to 0 and GMP was dead from the start (2026-10-09).
            # GMP_OH_FIX=False rebuilds the old (dead) indicators so pre-fix checkpoints still load (load_q_model).
            kw = {"oq_conf": QuantizerConfig("kbi", "table", k0=False, b0=1, i0=1, trainable=False,
                                             overflow_mode="SAT")} if GMP_OH_FIX["on"] else {}
            c = QUnaryFunctionLUT(f, name=f"oh_{tag}_{g}", **kw)(coord)
        else:
            c = layers.Lambda(f, name=f"oh_{tag}_{g}")(coord)
        cols.append(ops.reshape(c, (-1, n, 1)))
    return layers.Concatenate(axis=-1, name=f"oh_{tag}")(cols)


def _dwconv(ch, k, q, name, rank=2):
    if q:
        from hgq.layers import QConv1D, QConv2D
        L = QConv2D if rank == 2 else QConv1D
    else:
        L = layers.Conv2D if rank == 2 else layers.Conv1D
    return L(ch, k, padding="same", groups=ch, name=name)


def gmp_grid(x, eta, phi, ch, q, edges, k, name="gmp"):
    eo = onehot_bins(eta, edges, q, f"{name}_eta")
    po = onehot_bins(phi, edges, q, f"{name}_phi")
    cell = _einsum("bne,bnp->bnep", [eo, po], q, name=f"{name}_cell")
    grid = _einsum("bnep,bnc->bepc", [cell, x], q, name=f"{name}_scatter")
    conv = _dwconv(ch, k, q, f"{name}_dwconv")(grid)
    return _einsum("bnep,bepc->bnc", [cell, conv], q, name=f"{name}_gather")


def gmp_sep(x, eta, phi, ch, q, edges, k, name="gmp"):
    """Separable GMP: 1-D scatter/conv/gather along eta, then along phi, summed."""
    out = []
    for coord, tag in ((eta, "eta"), (phi, "phi")):
        oh = onehot_bins(coord, edges, q, f"{name}_{tag}")
        line = _einsum("bne,bnc->bec", [oh, x], q, name=f"{name}_{tag}_scatter")
        conv = _dwconv(ch, k, q, f"{name}_{tag}_dwconv", rank=1)(line)
        out.append(_einsum("bne,bec->bnc", [oh, conv], q, name=f"{name}_{tag}_gather"))
    return out[0] + out[1]


def patch_mha(x4, d, nh, q, name, attn_bits=None, share_qk=False):
    NP, P = x4.shape[1], x4.shape[2]
    dh = d // nh
    qv = _qdense_bits(d, q, attn_bits, f"{name}_wq")(x4)
    kv = qv if share_qk else _qdense_bits(d, q, attn_bits, f"{name}_wk")(x4)
    vv = _qdense_bits(d, q, None, f"{name}_wv")(x4)
    qv = ops.reshape(qv, (-1, NP, P, nh, dh)); kv = ops.reshape(kv, (-1, NP, P, nh, dh)); vv = ops.reshape(vv, (-1, NP, P, nh, dh))
    s = _einsum("bnphd,bnqhd->bnhpq", [qv, kv], q, name=f"{name}_qk")
    w = _softmax(s, q, name=f"{name}_softmax")
    o = _einsum("bnhpq,bnqhd->bnphd", [w, vv], q, name=f"{name}_av")
    o = ops.reshape(o, (-1, NP, P, d))
    return _qdense_bits(d, q, None, f"{name}_wo")(o)


def token_mha(x, d, nh, q, name, attn_bits=None, share_qk=False):
    T = x.shape[1]
    dh = d // nh
    qv = _qdense_bits(d, q, attn_bits, f"{name}_wq")(x)
    kv = qv if share_qk else _qdense_bits(d, q, attn_bits, f"{name}_wk")(x)
    vv = _qdense_bits(d, q, None, f"{name}_wv")(x)
    qv = ops.reshape(qv, (-1, T, nh, dh)); kv = ops.reshape(kv, (-1, T, nh, dh)); vv = ops.reshape(vv, (-1, T, nh, dh))
    s = _einsum("bthd,bshd->bhts", [qv, kv], q, name=f"{name}_qk")
    w = _softmax(s, q, name=f"{name}_softmax")
    o = _einsum("bhts,bshd->bthd", [w, vv], q, name=f"{name}_av")
    return _qdense_bits(d, q, None, f"{name}_wo")(ops.reshape(o, (-1, T, d)))


def _seq_proj(x, k, q, name):
    """Constant-weight projection along the particle axis: [B,N,D] -> [B,k,D] (Linformer E/F)."""
    N, D = x.shape[1], x.shape[2]
    if q:
        from hgq.layers import QEinsumDense
        kw = {k_: v for k_, v in (("iq_conf", _attn_dlane()), ("kq_conf", _attn_wconf())) if v is not None}
        return QEinsumDense("bnd,nk->bkd", output_shape=(k, D), name=name, **kw)(x)
    return layers.EinsumDense("bnd,nk->bkd", output_shape=(k, D), name=name)(x)


def linformer_attn(x, d, nh, k, q, name, attn_bits=None, share_qk=False, share_ef=True):
    """Single-stage Linformer attention: Q from all N particles, K/V projected to k rows with constant
    E/F matrices (shared E=F by default). Activation x activation cost: 2*N*k*d (k << N)."""
    N = x.shape[1]
    dh = d // nh
    qv = _qdense_bits(d, q, attn_bits, f"{name}_wq")(x)
    kv = qv if share_qk else _qdense_bits(d, q, attn_bits, f"{name}_wk")(x)
    vv = _qdense_bits(d, q, None, f"{name}_wv")(x)
    kp = _seq_proj(kv, k, q, f"{name}_E")
    vp = kp if (share_qk and share_ef) else _seq_proj(vv, k, q, f"{name}_F")
    if share_qk and share_ef:  # K==V rows share one projection; V needs its own values though
        vp = _seq_proj(vv, k, q, f"{name}_F")
    qv = ops.reshape(qv, (-1, N, nh, dh)); kp = ops.reshape(kp, (-1, k, nh, dh)); vp = ops.reshape(vp, (-1, k, nh, dh))
    s_ = _einsum("bnhd,bkhd->bhnk", [qv, kp], q, name=f"{name}_qk")
    w = _softmax(s_, q, name=f"{name}_softmax")
    o = _einsum("bhnk,bkhd->bnhd", [w, vp], q, name=f"{name}_av")
    return _qdense_bits(d, q, None, f"{name}_wo")(ops.reshape(o, (-1, N, d)))


def _qbn_dense(eq, shape, q, name, activation=None, bias_axes="C"):
    """JEDI-linear's dense: einsum + batchnorm folded into the kernel (QEinsumDenseBatchnorm) when quantized."""
    if q:
        from hgq.layers import QEinsumDenseBatchnorm
        return QEinsumDenseBatchnorm(eq, shape, bias_axes=bias_axes, activation=activation, name=name)

    def apply(x):
        h = layers.EinsumDense(eq, shape, bias_axes=bias_axes, name=name)(x)
        h = layers.BatchNormalization(name=name + "_bn")(h)
        return layers.Activation(activation, name=name + "_act")(h) if activation else h
    return apply


def build_jedi(num_particles=64, width=64, head_widths=(64, 32, 16), n_classes=5, quantized=False, uq1=True,
               gmp_mode="none", gmp_edges=None, gmp_bins=8, gmp_bounds=1.6, gmp_kernel=3, gmp_channels=16, name=None,
               n_feat=3, rounds=1, attn="none", attn_k=16, attn_d=16, jglobal="mean", jpatch=8, jheads=2):
    """JEDI-linear 'gnn' backbone (github.com/calad0i/JEDI-linear src/model.py get_gnn), optionally with a PHAT-JeT
    GMP message. Per particle: phi1 = MLP(x); interaction s = MLP(phi1), d = MLP(mean_n phi1), h = s + d (+ GMP msg);
    h = MLP(h); sum-pool; head MLP. uq1=True shares data-lane bit-widths across the particle axis (permutation-
    invariant, JEDI 'perminv'); uq1=False lets every particle slot learn its own bits (JEDI pT-sorted model).
    gmp_mode='grid': scatter the first `gmp_channels` of phi1 onto a static G x G (eta, phi) grid, depthwise conv,
    gather back, project to `width` and add to h (local geometric context that the global mean cannot carry)."""
    from math import log2
    q = quantized
    N, W = num_particles, width
    feats = keras.Input((N, n_feat), name="features")
    eta, phi = feats[..., 1], feats[..., 2]
    scopes = []
    if q:
        from hgq.config import QuantizerConfigScope
        scopes = [QuantizerConfigScope(place=("weight", "bias"), overflow_mode="SAT_SYM"),
                  QuantizerConfigScope(place="datalane", heterogeneous_axis=(-1,) if uq1 else None)]
    for s in scopes:
        s.__enter__()
    try:
        x = _qbn_dense("bnc,cC->bnC", (N, W), q, "embed", activation="relu")(feats)
        if q:
            from hgq.layers import QAdd, QSum
        for r in range(rounds):  # rounds>1: repeat the interaction (latency headroom); r=0 keeps the original layer names
            R = "" if r == 0 else f"_r{r + 1}"
            s_ = _qbn_dense("bnc,cC->bnC", (N, W), q, "interact_self" + R, activation="relu")(x)
            if jglobal == "mean":  # JEDI-linear global: mean over all particles
                if q:
                    m = QSum(axes=1, scale=2.0 ** -round(log2(N)), keepdims=True, name="interact_pool" + R)(x)
                else:
                    m = ops.sum(x, axis=1, keepdims=True) * 2.0 ** -round(log2(N))
                d_ = _qbn_dense("bnc,cC->bnC", (1, W), q, "interact_global" + R, activation="relu")(m)
                h = QAdd(name="interact_add" + R)([s_, d_]) if q else s_ + d_
            elif jglobal == "none":  # no global term: particles only meet through GMP (if any) and the final sum
                h = s_
            else:
                # PHAT-style hierarchical global instead of the JEDI mean: pT-ordered patches of `jpatch` particles are
                # pooled to tokens, reduced to 16 ch, mixed across patches (dense mixer or patch-token attention), projected
                # back to W and broadcast to each patch's particles.
                P = jpatch
                NPt = N // P
                h4 = ops.reshape(x, (-1, NPt, P, W))
                tok = QSum(axes=2, scale=1.0 / P, name="jpatch_tokens" + R)(h4) if q else ops.sum(h4, axis=2) * (1.0 / P)
                tok = _qbn_dense("bnc,cC->bnC", (NPt, 16), q, "jpatch_reduce" + R, activation="relu")(tok)
                if jglobal == "patch_mix":
                    flat = ops.reshape(tok, (-1, NPt * 16))
                    flat = _qbn_dense("bc,cC->bC", NPt * 16, q, "jpatch_mix" + R, activation="relu")(flat)
                    tok = ops.reshape(flat, (-1, NPt, 16))
                elif jglobal == "patch_attn":
                    tok = token_mha(tok, 16, jheads, q, "jpatch_attn" + R)
                else:
                    raise ValueError(jglobal)
                g = _qbn_dense("bnc,cC->bnC", (NPt, W), q, "jpatch_global" + R, activation="relu")(tok)
                g = ops.repeat(g, P, axis=1)
                h = QAdd(name="interact_add" + R)([s_, g]) if q else s_ + g
            if gmp_mode == "grid" and r == 0:
                if gmp_edges is None:
                    gmp_edges = _np.linspace(-gmp_bounds, gmp_bounds, gmp_bins + 1).tolist()
                C = gmp_channels or W
                xin = x if C == W else x[..., :C]
                msg = gmp_grid(xin, eta, phi, C, q, gmp_edges, gmp_kernel, name="gmp")
                msg = _qbn_dense("bnc,cC->bnC", (N, W), q, "gmp_pointwise")(msg)
                h = QAdd(name="gmp_add")([h, msg]) if q else h + msg
            if attn != "none" and r == 0:
                # parallel sparse attention branch (like GMP: a message added to h, not a serial block): only the leading
                # attn_k particles attend to each other; V = their first attn_d embedding channels (no Wv); relu or softmax
                # scores; one projection back to W. Its chain (Wq/Wk -> QK -> AV -> proj) is shorter than GMP's, so it
                # should cost LUTs but little or no latency (PHAT's serial attention cost +40-120 ns, 2026-10-10 screen).
                K, Cd = min(attn_k, N), attn_d
                xa = x[..., :K, :]
                qa = _qbn_dense("bnc,cC->bnC", (K, Cd), q, "jattn_q")(xa)
                ka = _qbn_dense("bnc,cC->bnC", (K, Cd), q, "jattn_k")(xa)
                if attn == "linear":
                    # linear attention, reassociated: out = Q (K^T V); K^T V is a d x d summary summed over particles (like
                    # JEDI's mean pool), so no K x K score matrix is ever built: cheaper and shallower than relu/softmax
                    kv = _einsum("bjc,bjd->bcd", [ka, xa[..., :Cd]], q, name="jattn_kv")
                    oa = _einsum("bkc,bcd->bkd", [qa, kv], q, name="jattn_qkv")
                else:
                    sc = _einsum("bkc,bjc->bkj", [qa, ka], q, name="jattn_qk")
                    wa = layers.ReLU(name="jattn_relu")(sc) if attn == "relu" else _softmax(sc, q, name="jattn_softmax")
                    oa = _einsum("bkj,bjc->bkc", [wa, xa[..., :Cd]], q, name="jattn_av")
                oa = _qbn_dense("bnc,cC->bnC", (K, W), q, "jattn_pointwise")(oa)
                if K < N:
                    hk = QAdd(name="jattn_add")([h[..., :K, :], oa]) if q else h[..., :K, :] + oa
                    h = layers.Concatenate(axis=-2, name="jattn_pad")([hk, h[..., K:, :]])
                else:
                    h = QAdd(name="jattn_add")([h, oa]) if q else h + oa
            h = _qbn_dense("bnc,cC->bnC", (N, W), q, "phi2" + R, activation="relu")(h)
            x = h
        if q:
            pooled = QSum(axes=1, scale=1 / 16, keepdims=False, name="agg_sum")(h)
        else:
            pooled = ops.sum(h, axis=1) * (1 / 16)
        z = pooled
        for i, hw in enumerate(head_widths):
            z = _qbn_dense("bc,cC->bC", hw, q, f"head{i + 1}", activation="relu")(z)
        logits = _qbn_dense("bc,cC->bC", n_classes, q, "head_out")(z)
    finally:
        for s in reversed(scopes):
            s.__exit__(None, None, None)
    return keras.Model(feats, logits, name=name or ("jedi_gnn" + ("_q" if q else "")))


def build_variant(
    num_particles=64, d_model=16, num_heads=4, patch_size=8, n_classes=5, quantized=False,
    gmp_mode="grid", gmp_edges=None, gmp_bins=8, gmp_bounds=1.6, gmp_kernel=3, gmp_channels=None,
    local_mode="mha", global_mode="mha", ffn_mult=1, pre_norm="tanh", attn_bits=None,
    parallel_attn=False, attn_particles=None, share_qk=False, use_head1=True, linf_k=4, unshared=False,
    ffn_hidden=None, mix_hidden=None, n_blocks=1, lut_layers=None, lut_dhl=8, name=None,
    arch="phat", jedi_width=64, jedi_uq1=True, jedi_head=(64, 32, 16), n_feat=3, jedi_rounds=1,
    jedi_attn="none", jedi_attn_k=16, jedi_attn_d=16, jedi_global="mean", jedi_patch=8, jedi_gheads=2,
):
    if arch == "jedi":
        return build_jedi(num_particles=num_particles, width=jedi_width, head_widths=jedi_head, n_classes=n_classes,
                          quantized=quantized, uq1=jedi_uq1, gmp_mode=gmp_mode, gmp_edges=gmp_edges, gmp_bins=gmp_bins,
                          gmp_bounds=gmp_bounds, gmp_kernel=gmp_kernel, gmp_channels=gmp_channels or 16, name=name,
                          n_feat=n_feat, rounds=jedi_rounds, attn=jedi_attn, attn_k=jedi_attn_k, attn_d=jedi_attn_d,
                          jglobal=jedi_global, jpatch=jedi_patch, jheads=jedi_gheads)
    UNSHARED["on"] = bool(unshared)
    LUT["roles"] = set((lut_layers or "").split(",")) - {""}
    LUT["d_hl"] = lut_dhl
    """attn_particles: if set (< num_particles), local attention runs only over the leading
    `attn_particles` (pT/kT-ordered head); the soft tail bypasses it (physics-informed pruning)."""
    q = quantized
    NP = num_particles // patch_size
    assert NP * patch_size == num_particles
    gmp_channels = gmp_channels or d_model
    if gmp_edges is None:
        gmp_edges = _np.linspace(-gmp_bounds, gmp_bounds, gmp_bins + 1).tolist()

    feats = keras.Input((num_particles, 3), name="features")
    eta, phi = feats[..., 1], feats[..., 2]
    # da4ml allows only ReLU inline; any other activation must be its own unary-LUT layer.
    if pre_norm in (None, "relu"):
        x = _pdense(d_model, q, activation=pre_norm, name="embed")(feats)
    else:
        x = _pdense(d_model, q, name="embed")(feats)
        if q:
            from hgq.layers import QUnaryFunctionLUT
            x = QUnaryFunctionLUT(getattr(ops, pre_norm), name="embed_act")(x)
        else:
            x = layers.Activation(pre_norm, name="embed_act")(x)

    par = PHAT_PARALLEL["on"]  # fully parallel block: GMP, local attention and the global stage all read the block input
    for bi in range(n_blocks):
        S = "" if bi == 0 else f"_b{bi}"
        msg_g, a_par = None, None
        if gmp_mode != "none":
            xin = x if gmp_channels == d_model else x[..., :gmp_channels]
            fn = gmp_grid if gmp_mode == "grid" else gmp_sep
            msg = fn(xin, eta, phi, gmp_channels, q, gmp_edges, gmp_kernel, name="gmp" + S)
            msg = _ldense("proj", d_model, q, name="gmp_pointwise" + S, per_particle=True)(msg)
            if par:
                msg_g = msg
            else:
                x = x + msg

        x0 = x
        if par:
            assert not attn_particles or attn_particles == num_particles, "phat_parallel needs attention over all particles"
        if local_mode == "linf":  # Linformer over the leading K particles (global, no patches)
            K = attn_particles or num_particles
            xa = x if K == num_particles else x[..., :K, :]
            a = linformer_attn(xa, d_model, num_heads, linf_k, q, "local_attn" + S, attn_bits, share_qk)
            if par:
                a_par = a
            elif K < num_particles:  # residual on the leading K only; the soft tail passes through (no zeros_like: not traceable)
                x = layers.Concatenate(axis=-2, name="attn_pad" + S)([x[..., :K, :] + a, x[..., K:, :]])
            else:
                x = x + a
        if local_mode == "mha":
            K = attn_particles or num_particles
            assert K % patch_size == 0 and K <= num_particles
            xa = x if K == num_particles else x[..., :K, :]
            h4 = ops.reshape(xa, (-1, K // patch_size, patch_size, d_model))
            a = patch_mha(h4, d_model, num_heads, q, "local_attn" + S, attn_bits, share_qk)
            a = ops.reshape(a, (-1, K, d_model))
            if par:
                a_par = a
            elif K < num_particles:  # residual on the leading K only; the soft tail passes through (no zeros_like: not traceable)
                x = layers.Concatenate(axis=-2, name="attn_pad" + S)([x[..., :K, :] + a, x[..., K:, :]])
            else:
                x = x + a

        if global_mode != "none":
            src = x0 if (parallel_attn or par) else x
            h4 = ops.reshape(src, (-1, NP, patch_size, d_model))
            if q:
                from hgq.layers import QSum
                tok = QSum(axes=2, scale=1.0 / patch_size, name="patch_tokens" + S)(h4)
            else:
                tok = ops.sum(h4, axis=2) * (1.0 / patch_size)
            if global_mode == "mha":
                tok = token_mha(tok, d_model, num_heads, q, "patch_attn" + S, attn_bits, share_qk)
                tok = _dense(d_model, q, name="patch_msg_proj" + S)(tok)
                msg = ops.repeat(tok, patch_size, axis=1)
            elif global_mode == "mix":
                flat = ops.reshape(tok, (-1, NP * d_model))
                mixed = _ldense("mix", mix_hidden or NP * d_model, q, activation="relu", name="patch_mix" + S)(flat)
                if mix_hidden and mix_hidden != NP * d_model:  # low-rank mixer: expand back to NP*d before the broadcast
                    mixed = _dense(NP * d_model, q, name="patch_mix2" + S)(mixed)
                mixed = ops.reshape(mixed, (-1, NP, d_model))
                tok = _dense(d_model, q, name="patch_msg_proj" + S)(mixed)
                msg = ops.repeat(tok, patch_size, axis=1)
            elif global_mode == "jedi":  # JEDI-linear interaction: x = relu(Ws x) + relu(Wd mean_n x) (replaces x, no residual)
                s_ = _pdense(d_model, q, activation="relu", name="interact_self" + S)(src)
                if q:
                    from hgq.layers import QSum
                    from math import log2
                    m = QSum(axes=1, scale=2.0 ** -round(log2(num_particles)), keepdims=True, name="interact_pool" + S)(src)
                else:
                    m = ops.sum(src, axis=1, keepdims=True) * 2.0 ** -round(_np.log2(num_particles))
                g = _ldense("mix", d_model, q, activation="relu", name="interact_global" + S)(m)
                x = s_ + ops.repeat(g, num_particles, axis=1)
                msg = None
            elif global_mode == "mean":
                if q:
                    from hgq.layers import QSum
                    g = QSum(axes=1, scale=1.0 / NP, name="global_token" + S)(tok)
                else:
                    g = ops.sum(tok, axis=1) * (1.0 / NP)
                g = _ldense("mix", d_model, q, activation="relu", name="patch_mix" + S)(g)
                g = _dense(d_model, q, name="patch_msg_proj" + S)(g)
                msg = ops.repeat(ops.reshape(g, (-1, 1, d_model)), num_particles, axis=1)
            else:
                raise ValueError(global_mode)
            if msg is not None:
                x = x + msg
        if par:  # sum the parallel branches: latency = slowest branch, not their sum
            for m_ in (msg_g, a_par):
                if m_ is not None:
                    x = x + m_

        if ffn_hidden or ffn_mult:
            h = _ldense("ffn", ffn_hidden or ffn_mult * d_model, q, activation="relu", name="ffn1" + S, per_particle=True)(x)
            x = x + _ldense("ffn", d_model, q, name="ffn2" + S, per_particle=True)(h)

    if q:
        from hgq.layers import QSum
        pooled = QSum(axes=1, scale=1.0 / num_particles, name="agg_mean")(x)
    else:
        pooled = layers.GlobalAveragePooling1D(name="agg_mean")(x)
    hd = _ldense("head", d_model, q, activation="relu", name="head1")(pooled) if use_head1 else pooled
    logits = _ldense("head", n_classes, q, name="head_out")(hd)
    return keras.Model(feats, logits, name=name or ("phat_var" + ("_q" if q else "")))


def freeze_attn_bits(qmodel, frac_bits, weight_bits):
    """'Quantize attention without QAT': on every attention sub-layer (name contains 'attn': Q/K/V/O projections, QK
    and AV einsums, softmax exp/inverse tables, Linformer E/F) set data-lane fractional bits to `frac_bits` and weight
    bit widths to `weight_bits`, and make all of that layer's quantizer parameters non-trainable (integer bits keep
    whatever trace_minmax calibrated). QAT then compresses only the rest of the network, so the EBOPs pressure can no
    longer drive attention to f < 0 and a constant output (diag_attn.py, 2026-10-08)."""
    import numpy as np_
    n = 0
    for layer in qmodel.layers:
        if "attn" not in layer.name:
            continue
        for w in layer.weights:
            path = w.path
            if "quantizer" not in path:
                continue
            leaf = path.split("/")[-1]
            if leaf == "f" and "kif" in path:
                w.assign(np_.full(w.shape, float(frac_bits), dtype="float32"))
            elif leaf == "b" and "kbi" in path:
                w.assign(np_.full(w.shape, float(weight_bits), dtype="float32"))
            if leaf in ("f", "i", "b", "k"):
                w.trainable = False
                n += 1
    return n


def transfer_weights(qmodel, fmodel):
    """Copy float weights into same-named Q layers (Q layers carry extra quantizer vars)."""
    fw = {l.name: l.get_weights() for l in fmodel.layers if l.get_weights()}
    n = 0
    for layer in qmodel.layers:
        if hasattr(layer, "moving_mean") and hasattr(layer, "bn_gamma") and layer.name + "_bn" in fw and layer.name in fw:
            # JEDI-style float EinsumDense(W, b) + BatchNormalization(γ, β, μ, var; ε=1e-3) -> HGQ QEinsumDenseBatchnorm,
            # which computes x·(W·s) + bias − mean·s with s = γ/sqrt(var + keras ε):
            # kernel=W, bias=β, γ=γ, mean=μ−b, var=var+1e-3−keras ε  (exactly the float function)
            (W, b), (g, beta, mu, var) = fw[layer.name], fw[layer.name + "_bn"]
            layer.kernel.assign(W)
            layer.bias.assign(beta)
            layer.bn_gamma.assign(g)
            layer.moving_mean.assign(mu - b)
            layer.moving_variance.assign(var + 1e-3 - keras.config.epsilon())
            n += 1
            continue
        if layer.name not in fw:
            continue
        src, dst = fw[layer.name], layer.get_weights()
        rep, si = list(dst), 0
        for di, w in enumerate(dst):
            if si < len(src) and src[si].shape == w.shape:
                rep[di] = src[si]; si += 1
        if si == len(src):
            layer.set_weights(rep); n += 1
    return n


# ----------------------------------------------------------------------------- build from a run config
def kw_from_args(a):
    """Model kwargs from a train_variant argparse namespace / config.json dict."""
    g = a.get if isinstance(a, dict) else (lambda k, d=None: getattr(a, k, d))
    ATTN_NORM["mode"] = g("attn_norm") or "softmax"  # older configs have no attn_norm -> softmax
    PHAT_PARALLEL["on"] = bool(g("phat_parallel"))
    edges = g("gmp_edges")
    if isinstance(edges, str):
        edges = [float(e) for e in edges.split(",")]
    return dict(num_particles=g("n"), d_model=g("d_model"), num_heads=g("heads"), patch_size=g("patch"),
                gmp_mode=g("gmp"), gmp_edges=edges, gmp_bins=g("gmp_bins"), gmp_bounds=g("gmp_bounds"),
                gmp_kernel=g("gmp_kernel"), gmp_channels=g("gmp_channels") or None, local_mode=g("local"),
                global_mode=g("global_mode"), ffn_mult=g("ffn_mult"), pre_norm=g("pre_norm") or None,
                attn_bits=g("attn_bits"), parallel_attn=bool(g("parallel_attn")),
                attn_particles=g("attn_particles") or None, share_qk=bool(g("share_qk")),
                use_head1=not g("no_head1"), linf_k=g("linf_k") or 4, unshared=bool(g("unshared")),
                ffn_hidden=g("ffn_hidden") or None, mix_hidden=g("mix_hidden") or None,
                n_blocks=g("n_blocks") or 1, lut_layers=g("lut_layers") or None, lut_dhl=g("lut_dhl") or 8,
                arch=g("arch") or "phat", jedi_width=g("jedi_width") or 64, jedi_uq1=not g("jedi_per_slot_bits"),
                jedi_head=tuple(int(v) for v in (g("jedi_head") or "64,32,16").split(",")),
                n_feat=int(g("features") or 3), jedi_rounds=int(g("jedi_rounds") or 1),
                jedi_attn=g("jedi_attn") or "none", jedi_attn_k=int(g("jedi_attn_k") or 16), jedi_attn_d=int(g("jedi_attn_d") or 16),
                jedi_global=g("jedi_global") or "mean", jedi_patch=int(g("jedi_patch") or 8), jedi_gheads=int(g("jedi_gheads") or 2))


GMP_OH_FIX = {"on": True}


def load_q_model(cfg, ckpt):
    """build_q_from_args + load_weights; checkpoints from before the GMP indicator fix (2026-10-09) have a different
    indicator-quantizer layout, so fall back to rebuilding the legacy indicators for them."""
    err = None
    for on in (True, False):
        GMP_OH_FIX["on"] = on
        m = build_q_from_args(cfg)
        try:
            m.load_weights(ckpt)
            m.gmp_oh_fix = on  # which indicator layout loaded (export_named_all.py records it)
            return m
        except ValueError as e:
            err = e
        finally:
            GMP_OH_FIX["on"] = True
    raise err


def build_q_from_args(a):
    """Quantized model with the exact HGQ2 quantizer scopes train_variant used (needed to load_weights
    from a .keras file: lambda-based GMP indicators cannot be deserialized by load_model)."""
    from hgq.config import LayerConfigScope, QuantizerConfigScope
    from hgq.constraints import MinMax
    from hgq.regularizers import MonoL1
    g = a.get if isinstance(a, dict) else (lambda k, d=None: getattr(a, k, d))
    floor = g("floor_bits") or 0.0
    fc = MinMax(floor, 16) if floor > 0 else None
    l1 = g("l1_reg") if g("l1_reg") is not None else 1e-8
    # ic bounds the weight integer bits: with i_decay_speed the integer bits of exactly-zero weights decayed without
    # limit and crossed float32's exponent range (~-128) at epoch ~3270 -> NaN in every JEDI-arch run (diag_nan.py, 2026-10-08)
    s0 = QuantizerConfigScope(default_q_type="kbi", b0=g("bw_k"), overflow_mode="wrap", i0=g("i0_w"),
                              fr=MonoL1(l1), ir=MonoL1(l1), i_decay_speed=1e-3, ic=MinMax(-24, 24), **({"fc": fc} if fc else {}))
    # datalane_overflow: "wrap" (default; values past the learned integer range wrap around) or "SAT" (saturate).
    # Linformer QAT learned to depend on wrap-around and became numerically fragile (2026-10-08 diagnosis) -> SAT.
    s1 = QuantizerConfigScope(default_q_type="kif", place="datalane", overflow_mode=g("datalane_overflow") or "wrap", f0=g("bw_a"),
                              i0=g("i0_a"), fr=MonoL1(l1), ic=MinMax(0, 12), **({"fc": fc} if fc else {}))
    ATTN_FLOOR["f"] = g("attn_floor") if (g("attn_floor") or 0) > 0 else None
    # input-side attention floors (the effective fix); off unless requested so older runs rebuild unchanged
    ATTN_FLOORS["f"] = g("attn_in_floor") if g("attn_in_floor") is not None else None
    ATTN_FLOORS["i"] = g("attn_ifloor") if g("attn_ifloor") is not None else None
    ATTN_FLOORS["wbits"] = g("attn_wbits") if g("attn_wbits") is not None else None
    # shared_bits: data-lane bit-widths shared across the particle axis (JEDI-linear 'perm-inv' quantization)
    s2 = QuantizerConfigScope(place="datalane", heterogeneous_axis=(-1,)) if g("shared_bits") else None
    with s0, s1, LayerConfigScope(beta0=0):
        if s2 is None:
            return build_variant(quantized=True, **kw_from_args(a))
        with s2:
            return build_variant(quantized=True, **kw_from_args(a))


