DATA = "/j-jepa-vol/phatjet-fpga/jets_150x3_kt.npz"  # paper units, kT-sorted (pT*dR desc), padding at the end


def sort_jets(x, sort):
    """Re-order constituents per jet. 'kt' = as stored; 'pt' = descending pT (the order CTL2 delivers, no sorter)."""
    if sort in (None, "kt"):
        return x
    if sort == "pt":
        idx = _np.argsort(-x[:, :, 0], axis=1, kind="stable")  # padding has pT=0 -> stays at the end
        return _np.take_along_axis(x, idx[:, :, None], axis=1)
    raise ValueError(sort)


DATA_HLS4ML = "/j-jepa-vol/phat-jet-aaron/data/hls4ml150p_c64_f16.npz"  # raw hls4ml 150p (prep_hls4ml_raw.py)
DATA_SRC = {"name": "ours", "features": 3}


def use_data(cfg_or_name):
    """Select the input pipeline for load_split: 'ours' (jets_150x3_kt.npz, paper robust units) or 'hls4ml'
    (JEDI-linear's exact inputs: raw pT, eta_rel, phi_rel of the leading N constituents in native pT order,
    standardized with the train-set mean/std over the leading N slots)."""
    name = cfg_or_name if isinstance(cfg_or_name, str) else (cfg_or_name.get("data") if isinstance(cfg_or_name, dict) else getattr(cfg_or_name, "data", None))
    DATA_SRC["name"] = name or "ours"
    nf = None if isinstance(cfg_or_name, str) else (cfg_or_name.get("features") if isinstance(cfg_or_name, dict) else getattr(cfg_or_name, "features", None))
    DATA_SRC["features"] = int(nf or 3)


def load_split(split, n, sort="kt"):
    """x_train/y_train (620k) or x_val/y_val (260k held-out test) sliced to the leading n particles."""
    if DATA_SRC["name"] == "hls4ml":
        # 'pt' = native order (what CTL2 delivers); 'kt' = the same leading-n pT particles re-ordered by kT = pT*dR
        # (descending), i.e. a firmware sorter on the n candidates in front of the model (its latency/LUTs count too)
        assert sort in ("pt", "kt") and (sort == "pt" or DATA_SRC["features"] == 3), sort
        d = _np.load(DATA_HLS4ML)
        cols = [5, 8, 11] if DATA_SRC["features"] == 3 else list(range(16))  # 16 = privileged-teacher inputs (training only)
        xtr = d["x_train"][:, :n, cols].astype(_np.float32)
        shift, scale = xtr.mean(axis=(0, 1), keepdims=True), xtr.std(axis=(0, 1), keepdims=True)  # permutation-free
        x = xtr if split == "train" else d["x_test"][:, :n, cols].astype(_np.float32)
        del xtr
        if sort == "kt":  # the firmware sorter's integer key (standalone/kt_sorter_alkaid.py, bit-exact vs its trace):
            # ptk = min(floor(pT/GeV), 1023), d = |floor(deta*128)|, |floor(dphi*128)|, key = ptk^2 (de^2 + dp^2) ~ kT^2;
            # descending, ties -> pT rank (stable); padding (pT=0) keeps key 0 and stays at the end
            ptk = _np.minimum(_np.floor(x[..., 0]), 1023).astype(_np.int64)
            dek, dpk = (_np.abs(_np.floor(x[..., c] * 128)).astype(_np.int64) for c in (1, 2))
            idx = _np.argsort(-(ptk ** 2 * (dek ** 2 + dpk ** 2)), axis=1, kind="stable")
            x = _np.take_along_axis(x, idx[:, :, None], axis=1)
        x = (x - shift) / scale
        y = _np.eye(5, dtype=_np.float32)[d["y_train" if split == "train" else "y_test"].astype(int)]
        return x, y
    d = _np.load(DATA)
    x = sort_jets(d[f"x_{split}"].astype(_np.float32), sort)[:, :n]
    return x, d[f"y_{split}"].astype(_np.float32)


# ----------------------------------------------------------------------------- metrics (paper protocol)
CLASSES = ["q", "g", "W", "Z", "t"]


def evaluate(logits, y):
    """Accuracy, macro OvO AUC, and background rejection at 80% signal efficiency for W/Z/t
    (background = q,g jets, as in the paper's test script). logits/y: [M,5]."""
    from sklearn.metrics import roc_auc_score, roc_curve
    p = _np.exp(logits - logits.max(1, keepdims=True)); p /= p.sum(1, keepdims=True)
    yi = y.argmax(1)
    out = dict(test_acc=float((p.argmax(1) == yi).mean()),
               test_auc=float(roc_auc_score(y, p, average="macro", multi_class="ovo")))
    rej = {}
    for i in (2, 3, 4):
        m = (yi == 0) | (yi == 1) | (yi == i)
        fpr, tpr, _ = roc_curve((yi[m] == i).astype(int), p[m, i])
        f = fpr[_np.argmin(_np.abs(tpr - 0.8))]
        rej[CLASSES[i]] = float(1.0 / f) if f > 0 else float("inf")
    out["bg_rej"] = rej
    out["avg_bg_rej"] = float(_np.mean(list(rej.values())))
    return out
